import 'package:flutter/material.dart'; import '../../automation/automation_manager.dart'; import '../widgets/glass_card.dart'; import 'notes_screen.dart'; import 'weather_screen.dart';
class ToolsScreen extends StatelessWidget{const ToolsScreen({super.key});@override Widget build(BuildContext c){final tools=[('Calculator',Icons.calculate),('Calendar',Icons.calendar_month),('Reminders',Icons.notifications),('Notes',Icons.note),('Weather',Icons.cloud),('Battery',Icons.battery_full),('Flashlight',Icons.flashlight_on),('Settings',Icons.settings)];return SafeArea(child:Padding(padding:const EdgeInsets.all(20),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const Text('Tools & Features',style:TextStyle(fontSize:28,fontWeight:FontWeight.bold)),const Text('Quick access to your favorite tools'),const SizedBox(height:20),Expanded(child:GridView.builder(itemCount:tools.length,gridDelegate:const SliverGridDelegateWithFixedCrossAxisCount(crossAxisCount:2,crossAxisSpacing:12,mainAxisSpacing:12),itemBuilder:(c,i)=>GlassCard(child:InkWell(onTap:()=>_tap(c,i,tools[i].$1),child:Column(mainAxisAlignment:MainAxisAlignment.center,children:[Icon(tools[i].$2,size:32),const SizedBox(height:10),Text(tools[i].$1),const SizedBox(height:4),const Text('Quick access',style:TextStyle(fontSize:11,color:Colors.white54))])))))])));}void _tap(BuildContext c,int i,String name){if(name=='Notes')Navigator.push(c,MaterialPageRoute(builder:(_)=>const NotesScreen()));if(name=='Weather')Navigator.push(c,MaterialPageRoute(builder:(_)=>const WeatherScreen()));if(name=='Flashlight')AutomationManager().execute('flashlight on');}}
